package com.nexamart.backend.service;
import com.nexamart.backend.api.ApiModels.*; import com.nexamart.backend.config.AppProperties; import com.nexamart.backend.domain.*; import com.nexamart.backend.exception.ApiException; import com.nexamart.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.net.URI; import java.net.URLEncoder; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service public class PartnerOtpService {
 private final OtpChallengeRepository challenges; private final UserAccountRepository users; private final AuthService auth; private final AppProperties props; private final SecureRandom random=new SecureRandom(); private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
 public PartnerOtpService(OtpChallengeRepository c,UserAccountRepository u,AuthService a,AppProperties p){challenges=c;users=u;auth=a;props=p;}
 @Transactional public OtpSendResponse send(String raw){String phone=normalize(raw); var u=users.findByPhone(phone).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Mobile number is not registered. Please create a delivery partner account first.")); if(u.getRole()!=Role.DELIVERY_PARTNER) throw new ApiException(HttpStatus.NOT_FOUND,"This mobile number is not registered as a delivery partner."); var prev=challenges.findTopByPhoneOrderByCreatedAtDesc(phone).orElse(null); if(prev!=null&&prev.getCreatedAt().plusSeconds(30).isAfter(Instant.now())) throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,"Please wait 30 seconds before requesting another OTP."); String otp=String.format("%06d",random.nextInt(1_000_000)); var ch=new OtpChallenge();ch.setPhone(phone);ch.setOtpHash(hash(phone,otp));ch.setExpiresAt(Instant.now().plusSeconds(props.getOtpTtlSeconds()));challenges.save(ch); String channel="SMS"; try{sendSms(phone,otp);}catch(Exception e){if(!props.isOtpDevMode()){challenges.delete(ch);throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"OTP service is not configured. Please contact support.");}channel="DEV";} return new OtpSendResponse(true,"OTP sent successfully.",props.getOtpTtlSeconds(),channel,props.isOtpDevMode()?otp:null); }
 @Transactional public LoginResponse verify(String raw,String otp){String phone=normalize(raw); if(otp==null||!otp.matches("\\d{6}"))throw new ApiException(HttpStatus.BAD_REQUEST,"Enter the 6-digit OTP."); var ch=challenges.findTopByPhoneOrderByCreatedAtDesc(phone).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"OTP not found. Please request a new OTP.")); if(ch.isVerified())throw new ApiException(HttpStatus.BAD_REQUEST,"This OTP has already been used."); if(ch.getExpiresAt().isBefore(Instant.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"OTP expired. Please request a new OTP."); if(ch.getAttempts()>=5)throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,"Too many incorrect attempts. Please request a new OTP."); ch.setAttempts(ch.getAttempts()+1); if(!MessageDigest.isEqual(ch.getOtpHash().getBytes(StandardCharsets.UTF_8),hash(phone,otp).getBytes(StandardCharsets.UTF_8))){challenges.save(ch);throw new ApiException(HttpStatus.BAD_REQUEST,"Incorrect OTP. Please try again.");} ch.setVerified(true);challenges.save(ch); UserAccount u=users.findByPhone(phone).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery partner account not found.")); if(u.getRole()!=Role.DELIVERY_PARTNER)throw new ApiException(HttpStatus.FORBIDDEN,"Delivery partner access required."); if(u.getStatus()!=AccountStatus.ACTIVE)throw new ApiException(HttpStatus.FORBIDDEN,"Account is not active.");u.setLastActiveAt(Instant.now());users.save(u);return auth.issueDeliveryPartnerSession(u); }
 private void sendSms(String phone,String otp)throws Exception{String key=props.getOtpApiKey();if(key==null||key.isBlank()){if(props.isOtpDevMode())return;throw new IllegalStateException("TWOFACTOR_API_KEY is not configured");} String json="{\"to\":\"+91"+phone+"\""+(props.getOtpTemplateName()!=null&&!props.getOtpTemplateName().isBlank()?",\"template_name\":\""+props.getOtpTemplateName().replace("\"","\\\"")+"\"":"")+",\"var1\":\""+otp+"\"}"; var req=HttpRequest.newBuilder(URI.create("https://2factor.in/API/V1/OTP/SEND")).timeout(Duration.ofSeconds(12)).header("X-API-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json,StandardCharsets.UTF_8)).build();var res=http.send(req,HttpResponse.BodyHandlers.ofString());String body=res.body()==null?"":res.body().toLowerCase(Locale.ROOT);if(res.statusCode()<200||res.statusCode()>=300||!(body.contains("\"status\":\"sent\"")||body.contains("\"status\": \"sent\"")||body.contains("\"status\":\"success\"")))throw new IllegalStateException("OTP provider rejected request");}
 private String normalize(String raw){if(raw==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Mobile number is required.");String d=raw.replaceAll("\\D","");if(d.startsWith("91")&&d.length()==12)d=d.substring(2);if(!d.matches("[6-9]\\d{9}"))throw new ApiException(HttpStatus.BAD_REQUEST,"Enter a valid 10-digit Indian mobile number.");return d;} private String hash(String p,String o){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((p+":"+o).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
